INSERT INTO `postulations` VALUES (1,2,1,'Bonjour,\r\n\r\nJe suis intéressé par votre projet et je souhaite mettre mes compétences à votre service pour sa réalisation.\r\n\r\nJe possède des connaissances en développement web, notamment en PHP, HTML, CSS, JavaScript et MySQL. J\'accorde une grande importance à la qualité du travail, au respect des délais et à une communication claire tout au long du projet.\r\n\r\nJe suis motivé à comprendre précisément vos besoins afin de vous proposer une solution adaptée, efficace et évolutive. Je reste disponible pour échanger davantage sur les détails du projet et répondre à toutes vos questions.\r\n\r\nMerci pour votre attention et j\'espère avoir l\'opportunité de collaborer avec vous.\r\n\r\nCordialement,\r\nJonathan Mundayi',180.00,10,'accepted','2026-05-25 10:45:49','2026-05-25 10:49:43'),(2,4,1,'Eu jjvdkdbdjdkdkd djdjdbdkd kdvsudhdbd djdkdbdkdnd djdkdbd d dkdndkdkd dkdkdvdndkd djdkndgf sjdkdkdvdj',400.00,20,'accepted','2026-05-25 12:09:32','2026-05-25 12:22:09'),(3,5,4,'Vsksbsvdkd skdjdvd dkdkdvdk djdkjddjdkd djdjdbf dkdcdkd',300.00,10,'accepted','2026-05-25 12:33:22','2026-05-25 12:39:41'),(4,1,4,'Gzldjdldk dkdkdbdg dkdldvdkd dkdvdkd k dkdldvd dkldvd',150.00,20,'rejected','2026-05-25 12:33:53','2026-05-25 12:47:11'),(5,1,1,'cvb,ovvybbgyfrdy tfvuvtcfyubyh wruiutctycvygvuycxrtcvuk h bnikdncuvsdhbi vnuisvn',120.00,20,'accepted','2026-05-25 12:35:36','2026-05-25 12:47:11'),(6,6,5,'Je suis un grand fan d\'Hitler',1939.00,1945,'accepted','2026-05-25 13:40:19','2026-05-25 13:42:31'),(7,3,1,'fgjn,kl;v,eicvno z;fpo ifzia,dkza bdiooazn,diznaidbuiazb iok,adzl jdia ndo,aodnaznediaz kdp^k,ap',100.00,20,'rejected','2026-05-26 00:56:48','2026-05-29 01:31:26'),(8,7,1,'Va te faire foudre\r\nJe suis le seul client',1500000.00,5,'rejected','2026-05-27 02:36:33','2026-05-27 02:37:25'),(9,8,1,'Rhhvvj',50.00,20,'rejected','2026-05-27 02:39:14','2026-05-27 02:40:16'),(10,9,1,'Hein Hitler',1945.00,20,'rejected','2026-05-27 02:41:46','2026-05-27 